# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.schedule import load_schedule
from hourglass.timesheet import timesheet_lines
from tests.support import data_file


def make_shift(worker, start=540, end=600):
    return Shift(worker, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_file_schedule(self):
        shifts = load_schedule(data_file("schedule.csv"))
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 3 shifts, 9.0 hours",
                "Quill: 2 shifts, 7.5 hours",
                "Odell: 2 shifts, 6.5 hours",
            ],
        )

    def test_busiest_first(self):
        rows = [make_shift("Ann"), make_shift("Bob", 0, 180)]
        lines = timesheet_lines(rows)
        self.assertTrue(lines[0].startswith("Bob"))

    def test_one_decimal(self):
        rows = [make_shift("Ann", 0, 50)]
        self.assertEqual(
            timesheet_lines(rows), ["Ann: 1 shifts, 0.8 hours"]
        )

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        rows = [make_shift("Ann"), make_shift("  ")]
        with self.assertRaises(ValueError):
            timesheet_lines(rows)
